# owner: platform
import unittest

from hourglass.timesheet import format_timesheet
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start, end))

class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        shifts = [
            make_shift("Brisa", "mon", 540, 600),
            make_shift("Corin", "mon", 540, 840),
            make_shift("Brisa", "tue", 540, 600)
        ]
        self.assertEqual(
            format_timesheet(shifts),
            [
                "Corin: 1 shifts, 5.0 hours",
                "Brisa: 2 shifts, 2.0 hours"
            ]
        )

    def test_one_decimal_place(self):
        shifts = [make_shift("Brisa", "mon", 0, 100)]
        self.assertEqual(
            format_timesheet(shifts),
            ["Brisa: 1 shifts, 1.7 hours"]
        )

    def test_ties_break_on_name(self):
        shifts = [
            make_shift("Zane", "mon", 540, 600),
            make_shift("Abel", "mon", 540, 600)
        ]
        lines = format_timesheet(shifts)
        self.assertTrue(lines[0].startswith("Abel"))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            format_timesheet([])

    def test_blank_worker(self):
        shifts = [make_shift("  ", "mon", 540, 600)]
        with self.assertRaises(ProjectError):
            format_timesheet(shifts)
